@dataclass
class EvalConfig:
    n_per_region: int = 1024
    seed: int = 0
    oversample: int = 6
    range_mode: str = "p99"
    bg_scale: float = 0.1
    entropy_runs: int = 10
    entropy_mode: str = "std"
